<script setup lang="ts">
import type { BsSubledgerCopy, BsSubledgerForm, BsSubledgerFilters, BsSubledgerView, BsSubledgerChoices } from '../types/subledgerPresentation'
import type { BsFxForm } from '../types/foreignExchangePresentation'
defineProps<{ copy: BsSubledgerCopy; view: BsSubledgerView; choices: BsSubledgerChoices; accountsTo: string }>()
const filters = defineModel<BsSubledgerFilters>('filters', { required: true })
const form = defineModel<BsSubledgerForm>('form', { required: true })
const fxForm = defineModel<BsFxForm>('fxForm', { required: true })
const visible = defineModel<boolean>('visible', { required: true })
const emit = defineEmits<{ retry: []; action: [id: string]; reverse: [id: string]; submit: []; validateAmount: []; retryFx: []; fxMapping: []; fxItem: []; fxSettlement: []; fxPreview: []; fxConfirm: []; fxReversal: [] }>()
function field<K extends keyof BsSubledgerForm>(key: K, value: BsSubledgerForm[K]) { form.value = { ...form.value, [key]: value } }
</script>
<template>
  <BsStack gap="lg">
    <BsPageHeader :title="copy.title" :subtitle="copy.policy" :context="view.context" :context-label="copy.contextLabel"/>
    <BsForeignExchangeWorkspace v-model:form="fxForm" :copy="view.fx.copy" :view="view.fx.view" :choices="view.fx.choices" @retry="emit('retryFx')" @mapping="emit('fxMapping')" @item="emit('fxItem')" @settlement="emit('fxSettlement')" @preview="emit('fxPreview')" @confirm="emit('fxConfirm')" @reversal="emit('fxReversal')"/>
    <BsText v-if="!view.allowed" role="status">{{ copy.denied }}</BsText>
    <template v-else>
      <BsCard padding="md"><BsStack gap="md">
        <BsFloatingField :label="copy.from"><BsInput :model-value="filters.from" type="date" :max="filters.asOf" @update:model-value="filters = { ...filters, from: String($event ?? '') }"/></BsFloatingField>
        <BsFloatingField :label="copy.asOf"><BsInput :model-value="filters.asOf" type="date" :min="filters.from" @update:model-value="filters = { ...filters, asOf: String($event ?? '') }"/></BsFloatingField>
        <BsFloatingField :label="copy.party"><BsSelect :model-value="filters.party" :label="copy.party" :options="[{ value: '', label: copy.allParties }, ...choices.parties]" option-label="label" option-value="value" native @update:model-value="filters = { ...filters, party: String($event) }"/></BsFloatingField>
        <BsTableDensity :model-value="filters.density" :disabled="!view.preferenceReady" :label="copy.density" :compact-label="copy.compact" :comfortable-label="copy.comfortable" @update:model-value="filters = { ...filters, density: $event }"/>
      </BsStack></BsCard>
      <BsText v-if="view.error" role="alert" tone="danger">{{ copy.loadError }}<BsButton @click="emit('retry')">{{ copy.retry }}</BsButton></BsText><BsSectionSkeleton v-else-if="view.loading" variant="table" :rows="5"/>
      <template v-else-if="view.found">
        <BsInline><BsButton v-for="action in view.actions" :key="action.id" :disabled="action.disabled" @click="emit('action', action.id)">{{ action.label }}</BsButton></BsInline><BsText v-if="view.setupRequired" role="status">{{ copy.setup }}<BsLink :to="accountsTo">{{ copy.accounts }}</BsLink></BsText>
        <BsCard padding="none" overflow="hidden"><BsHeading :level="2">{{ copy.openItems }}</BsHeading><BsDataTable :value="view.items" data-key="id" :density="filters.density" sticky-header max-height="32rem" :scroll-label="copy.scroll" :label="copy.openItems" :columns="[{ key: 'name', header: copy.party + '/' + copy.reference }, { key: 'issueDate', field: 'issueDate', header: copy.issueDate }, { key: 'dueDate', field: 'dueDate', header: copy.dueDate }, { key: 'original', field: 'original', header: copy.original }, { key: 'outstanding', field: 'outstanding', header: copy.outstanding }, { key: 'aging', field: 'aging', header: copy.aging }]"><template #empty>{{ copy.empty }}</template><template #cell-name="{ row }"><BsText emphasis="semibold">{{ row.name }}</BsText><BsText dir="ltr" size="xs" tone="muted">{{ row.reference }}</BsText></template></BsDataTable></BsCard>
        <BsCard padding="md"><BsHeading :level="2">{{ copy.aging }}</BsHeading><BsText size="sm" tone="muted">{{ copy.agingPolicy }}</BsText><BsDescriptionList :columns="3"><BsDescriptionItem v-for="bucket in view.aging" :key="bucket.id" :term="bucket.label">{{ bucket.value }}</BsDescriptionItem></BsDescriptionList></BsCard>
        <BsCard padding="none" overflow="hidden"><BsHeading :level="2">{{ copy.statement }}</BsHeading><BsText v-if="!view.statementAvailable" tone="muted">{{ copy.chooseParty }}</BsText><template v-else><BsDescriptionList :columns="3"><BsDescriptionItem v-for="total in view.totals" :key="total.id" :term="total.label">{{ total.value }}</BsDescriptionItem></BsDescriptionList><BsDataTable :value="view.movements" data-key="id" :density="filters.density" sticky-header max-height="32rem" :scroll-label="copy.scroll" :label="copy.statement" :columns="[{ key: 'date', field: 'date', header: copy.date }, { key: 'reference', field: 'reference', header: copy.reference }, { key: 'kind', field: 'kind', header: copy.kind }, { key: 'movement', field: 'movement', header: copy.movement }, { key: 'balance', field: 'balance', header: copy.balance }, { key: 'reason', field: 'reason', header: copy.reason }, { key: 'history', header: copy.history }]"><template #empty>{{ copy.empty }}</template><template #cell-history="{ row }"><BsLink :to="row.journalTo">{{ copy.journal }}</BsLink><BsText v-if="row.reverses" size="xs">{{ copy.reverses }}: {{ row.reverses }}</BsText><BsButton v-if="row.canReverse" :disabled="row.disabled" @click="emit('reverse', row.id)">{{ copy.reverse }}</BsButton></template></BsDataTable></template></BsCard>
        <BsCard v-if="view.showReconciliation" padding="none" overflow="hidden"><BsHeading :level="2">{{ copy.reconciliation }}</BsHeading><BsText size="sm" tone="muted">{{ copy.reconciliationPolicy }}</BsText><BsDataTable :value="view.reconciliation" data-key="id" :density="filters.density" :label="copy.reconciliation" :columns="[{ key: 'name', field: 'name', header: copy.control }, { key: 'gl', field: 'gl', header: copy.glBalance }, { key: 'subledger', field: 'subledger', header: copy.subledgerBalance }, { key: 'variance', field: 'variance', header: copy.variance }, { key: 'status', header: copy.status }]"><template #empty>{{ copy.empty }}</template><template #cell-status="{ row }">{{ row.status }}<BsText>{{ row.explanation }}</BsText></template></BsDataTable></BsCard>
        <BsDisclosure v-if="view.showLegacy" :summary="copy.legacy"><BsText size="sm" tone="muted">{{ copy.legacyPolicy }}</BsText><BsDataTable :value="view.legacy" data-key="id" :density="filters.density" :label="copy.legacy" :columns="[{ key: 'reference', field: 'reference', header: copy.reference }, { key: 'original', field: 'original', header: copy.original }, { key: 'settled', field: 'settled', header: copy.cashSettled }, { key: 'outstanding', field: 'outstanding', header: copy.outstanding }]"><template #empty>{{ copy.empty }}</template></BsDataTable></BsDisclosure>
      </template>
    </template>
    <BsRecordActionDialog v-model:visible="visible" :title="view.dialog.title" :pending="view.dialog.pending" :dirty="view.dialog.dirty" :error="view.dialog.error" size="lg" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="view.dialog.disabled" @submit="emit('submit')">
      <BsText v-if="view.dialog.reversal" tone="muted">{{ copy.reversalPolicy }}</BsText><template v-else>
        <BsFloatingField :label="copy.party"><BsSelect :model-value="form.party" :label="copy.party" :options="[{ value: '', label: '' }, ...choices.activeParties]" option-label="label" option-value="value" required native @update:model-value="field('party', String($event))"/></BsFloatingField><BsFloatingField :label="copy.control"><BsSelect :model-value="form.control" :label="copy.control" :options="choices.controls" option-label="label" option-value="value" required native @update:model-value="field('control', String($event))"/></BsFloatingField><BsFloatingField :label="view.dialog.offsetLabel"><BsSelect :model-value="form.offset" :label="view.dialog.offsetLabel" :options="[{ value: '', label: '' }, ...choices.offsets]" option-label="label" option-value="value" required native @update:model-value="field('offset', String($event))"/></BsFloatingField>
        <BsFloatingField :label="copy.reference"><BsInput :model-value="form.reference" required @update:model-value="field('reference', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.amount"><BsInput :model-value="form.amount" inputmode="decimal" required :aria-invalid="Boolean(view.dialog.amountError)" :aria-describedby="view.dialog.amountError ? 'subledger-amount-error' : undefined" @update:model-value="field('amount', String($event ?? ''))" @blur="emit('validateAmount')"/></BsFloatingField><BsText v-if="view.dialog.amountError" id="subledger-amount-error" role="alert" size="sm" tone="danger">{{ view.dialog.amountError }}</BsText>
      </template>
      <BsFloatingField :label="copy.date"><BsInput :model-value="form.date" type="date" required @update:model-value="field('date', String($event ?? ''))"/></BsFloatingField><BsFloatingField v-if="view.dialog.showDue" :label="copy.dueDate"><BsInput :model-value="form.due" type="date" :min="form.date" required @update:model-value="field('due', String($event ?? ''))"/></BsFloatingField><BsFloatingField v-if="view.dialog.showReason" :label="copy.reason"><BsInput :model-value="form.reason" required @update:model-value="field('reason', String($event ?? ''))"/></BsFloatingField>
      <BsFieldGroup v-if="view.dialog.showAllocations" :legend="copy.allocations"><BsText size="sm" tone="muted">{{ copy.allocationPolicy }}</BsText><BsText v-if="!view.dialog.allocationItems.length">{{ copy.noAllocationItems }}</BsText><BsBox v-for="row in view.dialog.allocationItems" :key="row.id"><BsFloatingField :label="row.reference"><BsInput :model-value="form.allocations[row.id]" inputmode="decimal" @update:model-value="field('allocations', { ...form.allocations, [row.id]: String($event ?? '') })"/></BsFloatingField><BsText size="sm">{{ copy.outstanding }}: {{ row.outstanding }}</BsText></BsBox></BsFieldGroup>
    </BsRecordActionDialog>
  </BsStack>
</template>
